# Check generated visual labels for unsafe text using AWS Bedrock Guardrails\nimport os\n\n# Bedrock SDK for content safety (text only)\nfrom boto3 import client as boto3_client\n\nclass VisualSafetyText:\n    \"\"\"Flag unsafe textual content found in visual labels.\n    \"\"\"\n    @staticmethod\n    def check_text(safety_report: dict) -> bool:\n        \"\"\"Determine whether the textual portion of the analysis is safe.\n        Args:\n            safety_report (dict): Dictionary containing a key \"text\" with a string value.\n        Returns:\n            bool: True if safe, False if unsafe.\n        \"\"\"\n        text = safety_report.get(\"text\", \"\")\n        # Instantiate Bedrock runtime client (uses AWS credentials from env)\n        bedrock = boto3_client(\"bedrock-runtime\", region_name=\"us-east-1\")\n        # Call the safety endpoint (text guardrails)\n        response = bedrock.post_content_moderation(\n            text=text,\n            contentType=\"plain/text\"\n        )\n        # Assume response contains a boolean \"safe\" field\n        return response.get(\"safe\", True)\n\n# -----------------------------------------------------------------------------\n# End of visual_safety_text.py\n# -----------------------------------------------------------------------------
